    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D); // forge cheatcode addr
    EtherStore store;
    function setUp() public {
        store = new EtherStore();
        vm.deal(address(this), 10 ether);
        store.deposit{value: 5 ether}();
    }
    receive() external payable {}
    function test_exploit_drains_store() public {
        Attacker a = new Attacker(store);
